// Reconstructs the skill's runtime state at a selected point by replaying the
// conversation's tracker events up to and including the anchor. The tracker is
// append-only and state is replay, so replaying the skill/block lifecycle and
// memory events IS the historical skill_state — the same relationship v1 relies
// on to show the flow at a selected event. Kept DOM-free and next to the other
// pure skill derivations so it can be unit-tested in isolation.
import {
  ConversationEventType,
  type BlockStatus,
  type Skill,
  type UnionEventType,
} from "../../types";
import type { BlockRuntimeStatus } from "./types";

export interface ReconstructedSkillState {
  /**
   * Per-block runtime status for the anchored skill, keyed by block flow id.
   * Mirrors the wire shape of skill_state.blocks so the consumer's lookup is
   * identical to live mode.
   */
  readonly blocks: Record<string, BlockStatus>;
  /** Memory values in effect at the anchor, keyed by memory entry name. */
  readonly memory: Record<string, { value: unknown }>;
  /** The flow/step position at the anchor (from the anchor's own scope). */
  readonly position: { readonly flowId: string | null; readonly stepId: string | null };
}

function isConversationEvent(
  event: UnionEventType,
): event is Extract<UnionEventType, { __typename: "ConversationEvent" }> {
  return event.__typename === "ConversationEvent";
}

// Maps an ordered-block lifecycle event to the block's status at that point.
// Entered/resumed → active, completed → completed, cancelled/interrupted →
// inactive: the same status vocabulary the engine emits in skill_state.blocks.
function blockStatusFromEvent(type: ConversationEventType): BlockRuntimeStatus | null {
  switch (type) {
    case ConversationEventType.OrderedBlockEntered:
    case ConversationEventType.OrderedBlockResumed:
      return "active";
    case ConversationEventType.OrderedBlockCompleted:
      return "completed";
    case ConversationEventType.OrderedBlockCancelled:
    case ConversationEventType.OrderedBlockInterrupted:
      return "inactive";
    default:
      return null;
  }
}

/**
 * Replays `events[0..anchorIndex]` (inclusive) to reconstruct the anchored
 * skill's state at that point: per-block status, the memory map, and the
 * position carried by the anchor.
 *
 * Block statuses are keyed by the block's compiled flow id (via `skill.blocks`)
 * so the consumer's existing `block.ordered_block_id` lookup serves both live and
 * historical modes. Memory replays across all scopes — the anchored skill's
 * conditions may read project/system entries too.
 */
export function deriveSkillStateAt(
  events: readonly UnionEventType[],
  anchorIndex: number,
  anchoredSkillId: string,
  skill: Skill,
): ReconstructedSkillState {
  const flowIdByBlockId = new Map<string, string>();
  for (const [blockId, block] of Object.entries(skill.blocks)) {
    flowIdByBlockId.set(blockId, block.ordered_block_id);
  }

  const blocks: Record<string, BlockStatus> = {};
  const memory: Record<string, { value: unknown }> = {};
  let latestStep: { flowId: string | null; stepId: string | null } | null = null;

  const end = Math.min(anchorIndex, events.length - 1);
  for (let index = 0; index <= end; index++) {
    const event = events[index];
    if (!isConversationEvent(event)) continue;

    if (
      event.conversationEventType === ConversationEventType.MemorySet &&
      typeof event.name === "string"
    ) {
      memory[event.name] = { value: event.value };
      continue;
    }
    if (
      event.conversationEventType === ConversationEventType.MemoryCleared &&
      typeof event.name === "string"
    ) {
      memory[event.name] = { value: null };
      continue;
    }

    if (event.skillId !== anchoredSkillId) continue;
    if (event.stepId) latestStep = { flowId: event.flowId ?? null, stepId: event.stepId };
    if (!event.blockId) continue;
    const status = blockStatusFromEvent(event.conversationEventType);
    if (status === null) continue;
    const flowId = flowIdByBlockId.get(event.blockId);
    if (flowId) blocks[flowId] = { status };
  }

  const anchor = events[Math.max(0, Math.min(anchorIndex, events.length - 1))];
  const anchorScope =
    anchor && isConversationEvent(anchor)
      ? { flowId: anchor.flowId ?? null, stepId: anchor.stepId ?? null }
      : { flowId: null, stepId: null };
  // The anchor's own flow/step wins; when it carries none (a chat message, a
  // skill-lifecycle event) fall back to the last step-bearing event of the
  // anchored skill so the active block still highlights a step.
  const position = anchorScope.stepId ? anchorScope : (latestStep ?? anchorScope);

  return { blocks, memory, position };
}
